def _public_id():
    return uuid.uuid4().int >> 75


def seed_policy_and_approve_existing_users(apps, schema_editor):
    Users = apps.get_model("common", "Users")
    RegistrationApprovalPolicy = apps.get_model(
        "common", "RegistrationApprovalPolicy"
    )

    RegistrationApprovalPolicy.objects.get_or_create(
        name="Default policy",
        defaults={
            "public_id": _public_id(),
            "mode": "auto",
            "require_email_verified": True,
            "require_phone_verified": True,
            "is_enabled": True,
        },
    )
    # Existing local/demo accounts predate email/admin approval, so keep them usable.
    Users.objects.all().update(
        is_email_verified=True,
        is_phone_verified=True,
        approval_status="approved",
    )


